     [string]$Command = 'help',

     [Parameter(Position = 1, ValueFromRemainingArguments)]
     [string[]]$CliArguments = @()
 )

 Set-StrictMode -Version Latest
 $ErrorActionPreference = 'Stop'
 Import-Module (Join-Path $PSScriptRoot 'TaskForge.Core.psm1') -Force -WarningAction SilentlyContinue

 try {
     $normalizedCommand = $Command.ToLowerInvariant()
     $repoRoot = Split-Path -Parent $PSScriptRoot
     $defaultConfigFile = Join-Path $repoRoot 'config/taskforge.config.json'

     if ($normalizedCommand -eq 'config') {
         $action = ''
         $rest = @()
         if ($CliArguments.Count -ge 1 -and -not $CliArguments[0].StartsWith('--')) {
             $action = $CliArguments[0].ToLowerInvariant()
             if ($CliArguments.Count -gt 1) {
                 $rest = @($CliArguments[1..($CliArguments.Count - 1)])
             }
         }
         else {
             throw 'config requires an action: set, get, or list.'
         }

         $options = ConvertFrom-TaskForgeArguments -Arguments $rest
         $configFile = if ($options.Contains('config-file')) {
             Get-RequiredOption -Options $options -Name 'config-file'
         }
         else {
             $defaultConfigFile
         }
         $config = Read-TaskForgeConfig -Path $configFile
         $asJson = if ($options.Contains('json')) { $true }
             elseif ($config.Contains('defaultJson')) { [bool]$config['defaultJson'] }
             else { $false }

         switch ($action) {
             'set' {
                 Assert-KnownOptions -Options $options -Allowed @('key', 'value', 'config-file', 'json')
                 $key = Get-RequiredOption -Options $options -Name 'key'
                 Assert-KnownConfigKey -Key $key
                 $value = Get-RequiredOption -Options $options -Name 'value'
                 $stored = if ($key -eq 'defaultJson') { ConvertTo-TaskForgeBool -Value $value } else { $value }
                 $config[$key] = $stored
                 Write-TaskForgeConfig -Path $configFile -Config $config
                 if ($asJson) {
                     Write-TaskForgeOutput -Value ([pscustomobject]@{ key = $key; value = $stored }) -AsJson $true
                 }
                 else {
                     "Set $key = $stored"
                 }
             }
             'get' {
                 Assert-KnownOptions -Options $options -Allowed @('key', 'config-file', 'json')
                 $key = Get-RequiredOption -Options $options -Name 'key'
                 Assert-KnownConfigKey -Key $key
                 $value = if ($config.Contains($key)) { $config[$key] } else { $null }
                 if ($asJson) {
                     Write-TaskForgeOutput -Value ([pscustomobject]@{ key = $key; value = $value }) -AsJson $true
                 }
                 elseif ($null -eq $value) {
                     "$key is not set."
                 }
                 else {
                     "$key = $value"
                 }
             }
             'list' {
                 Assert-KnownOptions -Options $options -Allowed @('config-file', 'json')
                 $settings = [ordered]@{}
                 foreach ($k in (Get-TaskForgeConfigKeys)) {
                     if ($config.Contains($k)) { $settings[$k] = $config[$k] }
                 }
                 if ($asJson) {
                     Write-TaskForgeOutput -Value ([pscustomobject]$settings) -AsJson $true
                 }
                 else {
                     $lines = [System.Collections.Generic.List[string]]::new()
                     $bannerPath = Join-Path $repoRoot 'assets/config.txt'
                     if (Test-Path -LiteralPath $bannerPath) {
