     }
     elseif ($config.Contains('dataFile') -and -not [string]::IsNullOrWhiteSpace([string]$config['dataFile'])) {
         Resolve-TaskForgeConfigPath -ConfigFile $configFile -Value ([string]$config['dataFile'])
     }
     else {
         $defaultDataFile
     }
     $asJson = if ($options.Contains('json')) { $true }
         elseif ($config.Contains('defaultJson')) { [bool]$config['defaultJson'] }
         else { $false }

     switch ($normalizedCommand) {
         'add' {
             Assert-KnownOptions -Options $options -Allowed @('title', 'description', 'data-file', 'json', 'config-file')
             $title = Get-RequiredOption -Options $options -Name 'title'
             $tasks = @(Read-TaskStore -Path $dataFile)
